insert into public.chat_upload_intents(id,conversation_id,created_by,object_path) values ('cccccccc-cccc-4ccc-8ccc-cccccccccccc','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','pending/fixture/photo.jpg');
insert into public.chat_attachments(message_id) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
