select public.fixture_denied($$select public.send_chat_message('dddddddd-dddd-4ddd-8ddd-dddddddddddd','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','retry')$$,'stored text replay denied');
select public.fixture_denied($$select public.create_chat_image_upload_intent('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','cccccccc-cccc-4ccc-8ccc-cccccccccccc','image/jpeg')$$,'stored intent replay denied');
select public.fixture_denied($$select public.finalize_chat_image_message('cccccccc-cccc-4ccc-8ccc-cccccccccccc','retry')$$,'stored image replay denied');
select public.fixture_denied($$insert into storage.objects(bucket_id,name) values('chat-images','pending/fixture/photo.jpg')$$,'chat upload denied');
select public.fixture_denied($$insert into storage.objects(bucket_id,name) values('meal-photos','meal-plans/11111111-1111-4111-8111-111111111111/fixture.jpg')$$,'plan photo upload denied');
select public.set_my_health_consent('v2',true,false);
select public.fixture_denied($$select public.send_chat_message('dddddddd-dddd-4ddd-8ddd-dddddddddddd','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','retry')$$,'storage only does not permit sharing');
set request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select public.fixture_assert((select count(*)=0 from public.chat_messages),'dietitian messages hidden');
select public.fixture_denied($$select public.review_meal_change_request('77777777-7777-4777-8777-777777777777','approved',null)$$,'reviewed meal request replay denied');
select public.fixture_assert(public.set_client_nutrition_target('11111111-1111-4111-8111-111111111111',null,null) is null,'nutrition clearing does not disclose removed payload');
select public.fixture_assert((select count(*)=0 from public.chat_attachments),'dietitian attachments hidden');
select public.fixture_assert((select count(*)=0 from public.chat_conversations),'dietitian conversations hidden');
select public.fixture_assert((select count(*)=0 from public.chat_read_states),'dietitian receipts hidden');
select public.fixture_assert((select count(*)=0 from public.get_dietitian_unread_counts()),'definer unread counts hidden');
select public.fixture_assert((select count(*)=0 from public.notifications),'health notification hidden');
