set request.jwt.claim.sub='44444444-4444-4444-8444-444444444444';
select public.fixture_assert((select count(*)=0 from public.chat_messages),'foreign dietitian still denied');
select public.fixture_assert(not public.can_process_my_chat_image('cccccccc-cccc-4ccc-8ccc-cccccccccccc'),'foreign validator denied');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.set_my_health_consent('v2',false,false);
select public.delete_chat_message('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
update public.chat_upload_intents set status='aborted',aborted_at=now() where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
