select public.fixture_denied($$update public.chat_upload_intents set validated_at=now() where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'$$,'validation write after negative preference denied');
set request.jwt.claim.sub='';
select public.fixture_denied($$select public.send_chat_message('dddddddd-dddd-4ddd-8ddd-dddddddddddd','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','retry')$$,'JWT missing denied');
reset role;
-- The actual producer function bodies must return before reading/building content.
select public.fixture_assert(not private.insert_activity_notification_once('33333333-3333-4333-8333-333333333333','client_activity','fixture','fixture','fixture',null,'dddddddd-dddd-4ddd-8ddd-dddddddddddd',null,null,current_date,now()),'activity producer skipped');
select public.fixture_assert(not private.notify_client_meal_plan_updated('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',current_date),'plan producer skipped');
select public.fixture_assert(private.upsert_notification_aggregate('33333333-3333-4333-8333-333333333333','chat','fixture','fixture','fixture',p_conversation_id=>'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa') is null,'aggregate producer skipped');
set role service_role;
select public.fixture_denied($$insert into public.measurements(client_id,weight) values('11111111-1111-4111-8111-111111111111',70)$$,'service core content denied');
select public.fixture_denied($$update public.meals set is_eaten=false where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'$$,'service meal content denied');
select public.fixture_denied($$update public.chat_messages set body='changed' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$$,'service chat content denied');
select public.fixture_denied($$update public.chat_upload_intents set validated_at=now() where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'$$,'service validation denied');
insert into public.notifications(recipient_id,category,conversation_id,body) values ('33333333-3333-4333-8333-333333333333','chat','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','must be skipped');
select public.fixture_assert((select count(*)=1 from public.notifications where category='chat'),'no new sensitive notification');
insert into private.push_occurrences(notification_id) values ('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
select public.fixture_assert((select count(*)=0 from private.push_occurrences),'new push occurrence skipped');
update private.push_deliveries set status='claimed' where id='ffffffff-ffff-4fff-8fff-ffffffffffff';
select public.fixture_assert((select status='disabled' from private.push_deliveries where id='ffffffff-ffff-4fff-8fff-ffffffffffff'),'existing push stopped at transition');
insert into public.notifications(recipient_id,category,body) values ('33333333-3333-4333-8333-333333333333','relationship','fixture');
select public.fixture_assert((select count(*)=1 from public.notifications where category='relationship'),'relationship notification unaffected');
reset role;
insert into public.appointments(id,client_id) values ('99999999-9999-4999-8999-999999999999',null);
insert into public.notifications(recipient_id,category,appointment_id) values ('33333333-3333-4333-8333-333333333333','appointment','99999999-9999-4999-8999-999999999999');
insert into public.notifications(recipient_id,category,appointment_id) values ('33333333-3333-4333-8333-333333333333','appointment','88888888-8888-4888-8888-888888888888');
select public.fixture_assert((select count(*)=1 from public.notifications where category='appointment'),'only real unlinked calendar notification exempt');
set role authenticated;
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.set_my_health_consent('v2',true,true);
reset role;
set request.jwt.claim.sub='';
set role service_role;
insert into public.measurements(client_id,weight) values ('11111111-1111-4111-8111-111111111111',70);
update public.meals set is_eaten=false where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
update public.chat_upload_intents set validated_at=now() where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
insert into private.push_occurrences(notification_id) values ('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');
select public.fixture_assert((select count(*)=1 from private.push_occurrences),'push eligible with sharing');
reset role;
update private.health_consent_settings set document_version='v3';
set role service_role;
select public.fixture_denied($$update public.chat_upload_intents set validated_at=now()+interval '1 second' where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc'$$,'service current version required');
delete from public.chat_upload_intents where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';
reset role;
select 'HEALTH_CONSENT_CHAT_CONTRACT_PASS' as result;
